"""Authored final-batch exercises with canonical text and verified citations."""
from pathlib import Path
import json, hashlib

ROOT=Path(__file__).resolve().parent.parent
R=ROOT/'_implementation/research'; B=R/'batch4'
q=json.loads((R/'quran-full.json').read_text(encoding='utf-8'))
t=json.loads((B/'tafsir.json').read_text(encoding='utf-8'))
old=json.loads((R/'quran-snapshot.json').read_text(encoding='utf-8'))
old3=json.loads((R/'batch3/tafsir.json').read_text(encoding='utf-8'))
prov=json.loads((R/'batch2-provenance.json').read_text(encoding='utf-8'))

def passage(ref):
 chapter,span=ref.split(':');a,b=span.split('-') if '-' in span else (span,span)
 rows=[q['verses'][f'{chapter}:{n}'] for n in range(int(a),int(b)+1)]
 return dict(ref=ref,arabic='\n'.join(v['arabic'] for v in rows),translation='\n'.join(v['translation'] for v in rows),url=f'https://quran.com/{ref}',translationUrl=f'https://quran.com/{ref}?translations=19')

def comment(ref):
 for source in [t,old3,q.get('tafsir',{}),old.get('tafsir',{})]:
  for row in source.values():
   if ref in row.get('ayahs',[]) or row.get('range')==ref:return row['citation_url']
 raise ValueError('Missing commentary '+ref)

def hadith(ref,note):
 c,n=ref.split(':')
 return dict(label=('Sahih al-Bukhari ' if c=='bukhari' else 'Sahih Muslim ')+n,url=f'https://sunnah.com/{ref}',kind='Primary hadith report',note=note)

def second(name,edition,ref):
 for page in json.loads((B/(name+'.json')).read_text(encoding='utf-8')):
  for row in page['results'][edition]:
   if ref in row.get('ayahs',[]) or row.get('range')==ref:return row['citation_url']
 raise ValueError((name,ref))

MET='https://www.metmuseum.org/essays/'
UM=MET+'the-art-of-the-umayyad-period-661-750';AB=MET+'the-art-of-the-abbasid-period-750-1258';OT=MET+'the-art-of-the-ottomans-before-1600'
