misinfo=[]
def claim(id,title,topic,text,verdict,evidence,correction,limit,skill,ref=None,report=None):
 x=dict(id=id,title=title,topic=topic,claim=text,verdict=verdict,evidence=[dict(title=a,text=b) for a,b in evidence],correction=correction,limit=limit,skill=skill,sources=[])
 if ref:x.update(passage=passage(ref),commentaryUrl=comment(ref.split('-')[0]))
 if report:x['sources'].append(hadith(*report))
 misinfo.append(x)
claim('anger-strength','What counts as strength?','Hadith reading','The cited report defines strength as defeating other people.','Contradicted by the cited text',[('The contrast','The report contrasts overcoming others with self-control in anger.'),('The scope','It describes a virtue; it is not a fitness or mental-health assessment.')],'Sahih al-Bukhari 6114 praises controlling oneself when angry.','This does not mean every form of physical strength is condemned.','Read the contrast instead of extracting one familiar word.',report=('bukhari:6114','Abu Hurayra’s report contrasts physical victory and self-control in anger.'))
claim('hidden-defect','Does a hidden defect matter?','Fair dealing','The cited report says concealing a defect cannot affect a sale’s blessing.','Contradicted by the cited text',[('Truth and disclosure','The report connects truth and disclosure with blessing.'),('Concealment','It explicitly contrasts this with lying or hiding a fact.')],'Sahih al-Bukhari 2079 warns about concealment rather than treating it as harmless.','The report is not a complete legal decision on a visitor’s real dispute.','Read both sides of a conditional statement.',report=('bukhari:2079','Hakim ibn Hizam’s report addresses buyer and seller truthfulness.'))
claim('cave-web','A detail beyond a brief cave report','Historical detail','Sahih al-Bukhari 3653 describes a spider spinning a web at the cave.','Beyond the cited evidence',[('The reported concern','Abu Bakr describes concern that the pursuers might see them.'),('The reply','The brief account records reassurance. It does not describe a spider’s web.')],'This particular report supports concern and reassurance; it does not supply the web detail.','Omission here does not establish the authenticity or inauthenticity of every other narration about the cave.','Check the exact cited report before importing a familiar detail.',report=('bukhari:3653','Abu Bakr’s brief report about the cave; previously retrieved in the canonical research set.'))
claim('night-date','An exact anniversary from a report?','Historical detail','The cited Night Journey report establishes an exact Gregorian anniversary.','Beyond the cited evidence',[('An event report','The account describes the journey and ascent.'),('A missing calendar claim','It does not supply an exact Gregorian day and month.')],'The selected report can support an event account without establishing the precise anniversary claimed.','This is a scope finding about the cited report, not a complete survey of all historical date discussions.','Separate evidence for an event from evidence for its date.',report=('bukhari:3887','Malik ibn Sasaa’s Night Journey report; previously retrieved for the Seerah source set.'))
claim('safa-wording','A phrase detached from its report','Quran context','“No blame” in 2:158 means the walk between Safa and Marwa may simply be omitted.','Needs context',[('The questioner’s inference','Urwa makes that inference in the cited report.'),('Aisha’s answer','Aisha rejects it and explains the earlier hesitation behind the wording.')],'Read the complete verse with Aisha’s explanation rather than treating the isolated phrase as a complete ruling.','Legal detail and school-specific discussion require more than this short exercise.','A source can preserve a mistaken question without endorsing it.','2:158',('bukhari:1643','Urwa’s question and Aisha’s correction about Safa and Marwa.'))
claim('garden-cause','Response or cause?','Quran context','Abu Talha’s offer of his garden caused 3:92 to be revealed.','Contradicted by the cited text',[('The sequence','The report places the verse’s revelation before Abu Talha’s offer.'),('The response','The garden is his response to the teaching he heard.')],'The cited report describes a response after revelation, not the garden offer as its cause.','A single account of response does not list every circumstance known about a verse.','Check the direction of the narrative sequence.','3:92',('bukhari:1461','Anas’s report about the beloved garden and charitable giving.'))
claim('spider-material','A house is not a tensile-strength claim','Quran wording','29:41 says spider silk is the weakest material in the world.','Beyond the cited evidence',[('The actual image','The verse names a spider’s house, not a laboratory measure of silk.'),('Retrieved commentary','Al-Muyassar explains the comparison in terms of reliance on protectors besides Allah.')],'The reading concerns a fragile refuge in a comparison about reliance. It does not present a materials-science ranking.','Do not turn this scope correction into an unsupported claim about the strongest or weakest fiber.','Keep an analogy’s stated subject separate from a modern measurement.','29:41')
claim('ancestry','Does ancestry settle honor?','Quran wording','49:13 names tribes in order to rank human worth by ancestry.','Contradicted by the cited text',[('Shared origin','The passage begins with shared human origin.'),('Its stated distinction','Al-Muyassar explains that ancestry is not the basis of superiority; the passage names taqwa.')],'The cited reading does not make ancestry a guarantee of honor.','The app does not judge any individual’s taqwa or assign a personal religious rank.','Read the reason and criterion actually stated in the passage.','49:13')
claim('payment','Ability to pay and a delay','Fair dealing','The cited report says delaying a due debt is harmless when the debtor is wealthy.','Contradicted by the cited text',[('The debtor’s ability','The report specifically concerns an able debtor.'),('Its evaluation','It describes the delay as injustice.')],'Sahih al-Bukhari 2400 does not excuse avoidable delay by the able debtor.','Do not apply this to genuine inability without checking the different facts and relevant sources.','Do not reverse a source’s condition.',report=('bukhari:2400','Abu Hurayra’s report about delay by an able debtor.'))
claim('truth-habit','The habit a report praises','Hadith reading','The cited report praises repeated lying as a path to righteousness.','Contradicted by the cited text',[('Two habits','The report contrasts truthfulness and falsehood.'),('Their direction','It connects truthfulness, not repeated lying, with righteousness.')],'Sahih al-Bukhari 6094 praises truthfulness and warns about lying.','The exercise does not decide the moral state of a named person or resolve every exceptional legal discussion about speech.','Check which verb belongs to which outcome.',report=('bukhari:6094','The report links habits of speech with their consequences.'))
