# Public-domain Natural Earth land geometry, already acquired for batch three.
geo=json.loads((R/'batch3/countries.geojson').read_text(encoding='utf-8'))
land=[]
for feature in geo['features']:
 geometry=feature['geometry'];polygons=geometry['coordinates'] if geometry['type']=='MultiPolygon' else [geometry['coordinates']]
 for polygon in polygons:
  ring=polygon[0]
  # Keep the connected reading area, without drawing national borders.
  if max(p[0] for p in ring)<-20 or min(p[0] for p in ring)>120 or max(p[1] for p in ring)<-35 or min(p[1] for p in ring)>60:continue
  land.append('M'+'L'.join(f'{(lon+20)*6:.1f},{(60-lat)*4:.1f}' for lon,lat,*_ in ring)+'Z')

bundles={
 'islamic-civilization-timeline':dict(events=events,landPaths=land,methodology='Twenty-four selected records from UNESCO and the Metropolitan Museum of Art cover political changes, learning, cities, trade and architecture from 661 to 1648 CE. Century bands use editorial numeric bounds for filtering; exact years and construction ranges retain the institution’s precision. The map uses public-domain Natural Earth land shapes with no political borders. It is regional orientation, not a map of historical sovereignty. No Quran passage is used to prove a later historical date.'),
 'halal-business-decisions':dict(cases=business,methodology='Twelve fictional two-stage dilemmas connect a source reading with an explicitly editorial modern application. Outcomes are written possibilities, not promised worldly results or judgments of a person. Canonical Quran text and Pickthall wording come from Quran MCP; Al-Muyassar provides concise explanation and Al-Qurtubi is linked for further legal discussion where fetched. Hadith notes are original paraphrases of specifically identified reports. The exercises do not certify a real transaction as halal, replace a qualified adviser or supply legal/financial advice.'),
 'revelation-context-explorer':dict(readings=readings,methodology='Ten selected passages pair canonical text with a named Sahih al-Bukhari report and links to fetched Al-Muyassar and full Arabic Ibn Kathir commentary. Transmitted occasions, general context and responses after revelation are kept distinct. Reliability labels identify the collection and do not independently regrade chains. A parallel account and retained narrative uncertainties prevent the selected report being mistaken for exhaustive history. Commentary notes and report summaries are original concise English paraphrases; no modern English hadith translation is republished.'),
 'family-islamic-learning-challenges':dict(packs=packs,methodology='Twelve single-sitting family packs combine a source reading question, an open discussion and a shared activity. Age bands are editorial suggestions and Pickthall’s historical English may need an adult’s explanation. Open prompts have no single graded answer. Activities are original applications beyond the fetched canonical text, not scholarly rulings from quran.ai, quran.com or quran.foundation. No child names, private stories, profiles or ongoing behavior records are collected. Every participant may pass.'),
 'islamic-misinformation-casebook':dict(cases=misinfo,methodology='Twelve constructed reading claims are checked against fixed, specifically identified sources. They are exercises in misquotation, context, sequence and evidence limits, not a list of measured viral trends or accusations about people. Classifications describe what the cited material supports. “Beyond the cited evidence” does not mean that every other source has been searched or that the broader proposition is false. The app accepts no arbitrary claim for live judgment. Quran readings are canonical, and commentary and hadith notes remain attributed original paraphrases.'),
}

def save(slug,data):
 app=ROOT/'apps'/slug;path=app/'src/data/content.json'
 path.write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
 sources={}
 def add(label,url,kind,note=''):
  sources[url]=dict(label=label,url=url,kind=kind,note=note)
 def collect(value):
  if isinstance(value,list):
   for v in value:collect(v)
  elif isinstance(value,dict):
   if 'translationUrl' in value:add('Quran '+value['ref']+' · Marmaduke Pickthall',value['translationUrl'],'Canonical Quran reading','Uthmani Hafs Arabic and historical Pickthall English wording, retrieved through official Quran MCP.')
   if 'commentaryUrl' in value:add('Al-Tafsir al-Muyassar',value['commentaryUrl'],'Fetched Arabic commentary','English notes are original concise paraphrases, not verbatim translations.')
   if 'secondCommentaryUrl' in value:add('Ibn Kathir · full Arabic' if slug=='revelation-context-explorer' else 'Al-Qurtubi',value['secondCommentaryUrl'],'Fetched Arabic commentary','Further commentary; the full work includes discussion beyond the short activity.')
   for source in value.get('sources',[]):add(source['label'],source['url'],source['kind'],source.get('note',''))
   for v in value.values():collect(v)
 collect(data)
 if 'landPaths' in data:add('Natural Earth · public-domain land data','https://www.naturalearthdata.com/about/terms-of-use/','Map geometry','Bundled simplified land outlines; national borders are not displayed.')
 (app/'src/data/sources.json').write_text(json.dumps(list(sources.values()),ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
 p={k:prov[k] for k in ['provider','endpoint','retrievedAt','quranEdition','translationEdition','snapshotSha256']}
 p.update(appContentSha256=hashlib.sha256(path.read_bytes()).hexdigest(),batch='4',batchCommentaryRetrievedAt=json.loads((B/'provenance.json').read_text(encoding='utf-8'))['retrievedAt'],commentaryEditions=['ar-muyassar']+(['ar-ibn-kathir'] if slug=='revelation-context-explorer' else ['ar-qurtubi'] if slug=='halal-business-decisions' else []),sourceEvidence='Repository _implementation/research/batch4/; older matching canonical snapshots and specifically identified report caches are reused.',editorial=True)
 (app/'src/data/provenance.json').write_text(json.dumps(p,indent=2)+'\n',encoding='utf-8')
 print(slug,len(sources),'sources')

if __name__=='__main__':
 for slug,data in bundles.items():save(slug,data)
